const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountResolution(api){
 const panel=document.createElement('section');panel.id='resolution-panel';panel.className='resolution-panel';panel.setAttribute('aria-label','Guided game resolution');$('.match-layout').before(panel);
 function render(){const s=api.state();if(!s)return;const a=api.resolver.auto(s),c=a.choice,attack=a.attack,stats=attack?api.resolver.stats(s,attack.ref):null;
  panel.innerHTML='<div class="resolution-header"><b>✦ '+esc(a.gameOver?'Game ended':c?.title||s.step||'Core game procedures')+'</b><label><input id="auto-enabled" type="checkbox" '+(a.enabled?'checked':'')+'> Guided resolution</label><button id="core-rules">Check core rules</button><button id="effect-tools">Effects & corrections</button><a class="support-link" href="automation-support.html" target="_blank" rel="noopener">Ability support ↗</a></div>'+(a.gameOver?'<p class="bad">Player '+a.gameOver.players.map(p=>p+1).join(' & ')+' loses · '+esc(a.gameOver.reason)+'</p>':'')+(stats?'<div class="attack-soul"><b>'+esc(attack.type.toUpperCase())+' · Soul '+stats.soul+'</b><button id="soul-breakdown">Soul & power breakdown'+(stats.unsupported.length?' · review abilities':'')+'</button></div>':'')+(c?choiceHTML(c):'<p class="resolution-idle">'+(a.enabled?'Attacks use a guided sequence. Mandatory choices and ability check timings pause here. Other card effects remain manual.':'Manual mode. Existing controls remain available; turn guided resolution on to automate core procedures.')+'</p>')+(a.results[0]?'<details><summary>Last damage: '+esc(a.results[0].label)+' · '+(a.results[0].canceled?'canceled':a.results[0].n+' to clock')+'</summary><p>Revealed '+a.results[0].uids.length+' card(s). This outcome applies only to that damage instance.</p></details>':'');
  $('#auto-enabled').onchange=e=>api.commit('Changed guided resolution',()=>{if(a.choice||a.attack||a.queue.length)throw Error('Finish the pending resolution or use the explicit abort override.');a.enabled=e.target.checked;});
  $('#core-rules').onclick=()=>api.commit('Check core procedures',()=>api.resolver.run(s));$('#effect-tools').onclick=effectsDialog;
  if($('#soul-breakdown'))$('#soul-breakdown').onclick=()=>breakdown(attack.ref);
  panel.querySelectorAll('[data-response]').forEach(b=>b.onclick=()=>{const extras={};if($('#battle-atk')){extras.attacker=+$('#battle-atk').value;extras.defender=+$('#battle-def').value;}api.commit('Resolution choice: '+b.textContent,()=>api.resolver.respond(s,c.id,b.dataset.response,extras));});
  panel.querySelectorAll('[data-choice-inspect]').forEach(b=>b.onclick=()=>api.inspect(b.dataset.choiceInspect));
  for(const id of ['next-phase-middle','advance','previous-phase'])if($('#'+id))$('#'+id).disabled=!!(a.choice||a.attack||a.queue.length||a.gameOver);
  document.querySelectorAll('.auto-soul').forEach(b=>b.onclick=e=>{e.stopPropagation();const [p,z,uid]=b.dataset.soul.split('|');breakdown({p:+p,z,uid});});
  window.dispatchEvent(new window.Event('resize'));
 }
 function choiceHTML(c){return (c.kind==='checkpoint'?'<p class="timing-note">Check timing · resolve pending AUTO abilities in turn-player order. This is not a timing to play an arbitrary event or ACT ability. Confirm only after required abilities are resolved.</p>':'')+(c.kind==='counter'?'<p class="timing-note">Defender only: one counter-icon event or activated ability. Backup checks level and stock; events additionally check color. Printed restrictions and unsupported costs must be verified manually.</p>':'')+(c.kind==='level-order'?'<p>Choose the next card for waiting room, first → last. The group of six remains reserved until its order is complete.</p>':'')+(c.unsupported?.length?'<details class="unsupported"><summary>'+c.unsupported.length+' card text(s) require manual review</summary>'+c.unsupported.map(x=>'<p><b>'+esc(x.code||'Manual effect')+'</b> '+esc(x.text)+'</p>').join('')+'</details>':'')+(c.cards&&c.kind==='damage-view'?'<div class="resolution-reveals">'+c.cards.map(id=>api.image(id)).join('')+'</div>':'')+(c.kind==='battle'?'<div class="battle-inputs"><label>Attacker current power<input id="battle-atk" type="number" value="'+c.attacker.power+'"></label><label>Defender current power<input id="battle-def" type="number" value="'+c.defender.power+'"></label><span>Confirm power after manual effects. Unsupported abilities are not included automatically.</span></div>':'')+'<div class="resolution-choices">'+c.options.map(o=>'<div><button data-response="'+esc(o.value)+'">'+esc(o.label)+'</button>'+(o.card?'<button class="choice-inspect" data-choice-inspect="'+esc(o.card)+'" aria-label="Inspect choice card">⤢</button>':'')+'</div>').join('')+'</div>';
 }
 function breakdown(r){const stats=api.resolver.stats(api.state(),r);api.dialog('<p class="eyebrow">CURRENT CHARACTER VALUES</p><h2>Soul '+stats.soul+' · Power '+stats.power+'</h2><p>Damage is not dealt when soul is zero or less. Side-attack and trigger adjustments last until end of turn.</p><ul>'+stats.breakdown.map(e=>'<li>'+esc(e.label)+' · '+(e.soul||0)+' soul · '+(e.power||0)+' power</li>').join('')+'</ul>'+(stats.unsupported.length?'<h3>Manual review required</h3>'+stats.unsupported.map(x=>'<p><b>'+esc(x.code)+'</b> '+esc(x.text)+'</p>').join(''):'<p>No unrecognized text on this player’s current stage or climax area.</p>')+'<p>Use Effects & corrections to record unsupported modifiers. Text on cards in other zones may also require manual handling.</p>');}
 function effectsDialog(){const s=api.state(),refs=[0,1].flatMap(p=>api.resolver.allStage(s,p));api.dialog('<h2>Effects & manual corrections</h2><p>Record only the modifier described by the card. Other text and conditions remain manual. A turn-duration modifier expires during end-phase cleanup; a persistent modifier must be removed manually.</p><label>Character<select id="effect-target">'+refs.map(r=>'<option value="'+r.p+'|'+r.z+'|'+r.uid+'">P'+(r.p+1)+' · '+esc(api.name(api.resolver.inst(s,r).id))+'</option>').join('')+'</select></label><div class="two"><label>Soul adjustment<input id="effect-soul" type="number" value="0"></label><label>Power adjustment<input id="effect-power" type="number" value="0"></label></div><label>Level adjustment<input id="effect-level" type="number" value="0"></label><label>Source / condition<input id="effect-label" value="Manual card effect"></label><label>Duration<select id="effect-duration"><option value="turn">Until end of this turn</option><option value="persistent">Until removed manually</option></select></label><button id="apply-effect">Apply modifier</button><h3>Additional damage instance</h3><label>Receiving player<select id="effect-player"><option value="0">Player 1</option><option value="1">Player 2</option></select></label><label>Damage<input id="effect-damage" type="number" min="1" max="50" value="1"></label><p>Finish pending choices first. Damage source is the chosen character, including Shot tracking.</p><button id="deal-effect">Resolve separate damage</button><h3>Active recorded modifiers</h3>'+api.resolver.auto(s).effects.map((e,i)=>'<p>'+esc(e.label)+' · '+(e.soul||0)+' soul / '+(e.power||0)+' power <button data-clear-effect="'+i+'">Remove</button></p>').join('')+'<details><summary>Resolution overrides</summary><p>Undo is preferred. Abort retains moved cards but clears the unfinished sequence; use manual tools to correct zones, then check core rules.</p><button id="abort-resolution">Abort pending sequence (manual correction)</button><label><input id="cost-suspension" type="checkbox" '+(s.cost?'checked':'')+'> Paying a complete multi-part cost: defer refresh and level-up</label></details>');
  const ref=()=>{const [p,z,uid]=$('#effect-target').value.split('|');return {p:+p,z,uid};};
  $('#apply-effect').onclick=()=>{const r=ref(),vals={soul:+$('#effect-soul').value,power:+$('#effect-power').value,level:+$('#effect-level').value},label=$('#effect-label').value,duration=$('#effect-duration').value;api.commit('Recorded manual modifier',()=>api.resolver.manualEffect(s,r,vals,label,duration));effectsDialog();};
  $('#deal-effect').onclick=()=>{const p=+$('#effect-player').value,n=+$('#effect-damage').value,source=ref().uid;if(!Number.isInteger(n)||n<1||n>50)return;api.commit('Separate damage instance',()=>api.resolver.damage(s,p,n,source));$('#dialog').close();};
  document.querySelectorAll('[data-clear-effect]').forEach(b=>b.onclick=()=>{api.commit('Removed manual modifier',()=>api.resolver.auto(s).effects.splice(+b.dataset.clearEffect,1));effectsDialog();});
  $('#abort-resolution').onclick=()=>{api.commit('Aborted guided sequence for manual correction',()=>{const a=api.resolver.auto(s);a.choice=null;a.queue=[];a.attack=null;a.damage=null;a.trigger=null;a.gameOver=null;s.step='Attack declaration';});$('#dialog').close();};
  $('#cost-suspension').onchange=e=>api.commit('Cost payment '+(e.target.checked?'started':'ended'),()=>s.cost=e.target.checked);
 }
 return {render,breakdown};
}

